const fs = require('fs'); const path = require('path');
const root = path.join(__dirname, '..'); const skip = new Set(['node_modules','lib','lib-commonjs','dist','release','temp','sharepoint','solution','jest-output','debug']);
const files = []; function walk(dir) { for (const name of fs.readdirSync(dir)) { if (skip.has(name)) continue; const full = path.join(dir, name); const stat = fs.statSync(full); if (stat.isDirectory()) walk(full); else if (/\.(ts|tsx|js|json|scss)$/.test(name) && (/\/src\//.test(full) || /\/config\//.test(full))) files.push(full); } } walk(root);
const text = files.map(f => fs.readFileSync(f, 'utf8')).join('\n'); const bad = [ /\.post\s*\(/i, /\.put\s*\(/i, /\.patch\s*\(/i, /\.delete\s*\(/i, /method\s*:\s*['"](?:POST|PUT|PATCH|DELETE)/i, /@microsoft\/graph|graph\.microsoft/i, /roleassignments|PermissionKind|effectivepermissions/i, /clientSecret|apiKey|password\s*:/i, /\$top\s*[:=]\s*(?![^\n]*LIMITS\.page)/i ];
const hits = bad.flatMap(re => { const m = text.match(re); return m ? [re.toString()] : []; }); if (hits.length) { console.error(`Read-only verifier failed: ${hits.join(', ')}`); process.exit(1); } console.log(`Read-only verifier passed (${files.length} files).`);
